package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	x := token()
	target := int(num())
	// cnt[s][t]: prefixes with digit sum s; t = 1 while the prefix still equals X's prefix.
	cnt := make([][2]int64, target+1)
	cnt[0][1] = 1
	for _, ch := range x {
		bound := int(ch - '0')
		next := make([][2]int64, target+1)
		for s := 0; s <= target; s++ {
			for t := 0; t < 2; t++ {
				c := cnt[s][t]
				if c == 0 {
					continue
				}
				limit := 9
				if t == 1 {
					limit = bound
				}
				for d := 0; d <= limit && s+d <= target; d++ {
					nt := 0
					if t == 1 && d == bound {
						nt = 1
					}
					next[s+d][nt] += c
				}
			}
		}
		cnt = next
	}
	answer := cnt[target][0] + cnt[target][1]
	if answer == 0 {
		answer = -1
	}
	fmt.Println(answer)
}
